 demo.db.prepare("UPDATE branch_staff_role SET revoked_at=?,revoked_by=? WHERE branch_id=1 AND staff_id=? AND role_code='cashier'").run(demo.app.auth.now(),manager,cashierId);
 assert.equal((await pay(cash)).status,403);
 demo.db.prepare("UPDATE branch_staff_role SET revoked_at=NULL,revoked_by=NULL WHERE branch_id=1 AND staff_id=? AND role_code='cashier'").run(cashierId);
 assert.equal((await pay({...cash,amountCents:9000})).status,409);
 const afterFinance=await (await fetch(base+'/api/finance?branchId=1&patientId=1',{headers:cashier})).json();
 assert.equal(afterFinance.items[0].summary.unpaidCents,4000);
 assert.equal(demo.db.prepare('SELECT branch_id FROM patient_payment WHERE id=?').get(payReceipt.id).branch_id,1);
 const electronic={...cash,channel:'微信',externalReference:'演示流水-001',amountCents:2000,requestKey:'demo-electronic-1',
  expectedBillRevision:afterFinance.items[0].revision,expectedFundsRevision:afterFinance.items[0].fundsRevision};
 const payElectronic=value=>fetch(base+'/api/finance/payment',{method:'POST',headers:cashier,body:JSON.stringify(value)});
 const missingRef={...electronic,requestKey:'missing-reference'};delete missingRef.externalReference;
 assert.equal((await payElectronic(missingRef)).status,422);
 assert.equal((await pay(electronic)).status,422);
 const electronicReceipt=await payElectronic(electronic);assert.equal(electronicReceipt.status,200);
 const mid=await (await fetch(base+'/api/finance?branchId=1&patientId=1',{headers:cashier})).json();assert.equal(mid.items[0].summary.unpaidCents,2000);
 const duplicate={...electronic,requestKey:'duplicate-reference',expectedBillRevision:mid.items[0].revision,expectedFundsRevision:mid.items[0].fundsRevision};
 const duplicateResult=await payElectronic(duplicate);assert.equal(duplicateResult.status,409);assert.equal((await duplicateResult.json()).code,'PAYMENT_DUPLICATE');
 const finalPayment={...cash,requestKey:'final-cash',amountCents:2000,expectedBillRevision:mid.items[0].revision,expectedFundsRevision:mid.items[0].fundsRevision};
 assert.equal((await pay(finalPayment)).status,200);
 const settled=await (await fetch(base+'/api/finance?branchId=1&patientId=1',{headers:cashier})).json();
 assert.equal(settled.items[0].summary.unpaidCents,0);assert.ok(settled.items[0].payments.some(p=>p.channel==='微信'&&p.external_reference==='演示流水-001'));
